    my $command = shift;

    my $project = $self->sqitch->project;
    my $config = $self->sqitch->config;

    my $top_dir = dir( $self->dest_top_dir($project) );

    # Create the destination directories.
    $top_dir->mkpath;
    $top_dir->file('script')->mkpath;
    $top_dir->file('deploy')->mkpath;
    $top_dir->file('verify')->mkpath;
    $top_dir->file('revert')->mkpath;

    # Copy the configuration file.
    my $config_file = $config->local_file;
    $self->_copy_if_modified( $config_file, $top_dir->file( $config_file->basename ) );

    # Copy the plan file.
    my $plan_file = $project->plan_file;
    $self->_copy_if_modified( $plan_file, $top_dir->file( $plan_file->basename ) );

    # Copy the change files.
    my $dir_for = $self->dest_dirs_for($project);
    for my $change ( $project->plan->changes ) {
        my $prefix = $change->is_reworked ? 'reworked_' : '';
        my @path = $change->path_segments;
        if (-e ( my $file = $change->deploy_file )) {
            $self->_copy_if_modified(
                $file,
                $dir_for->{"${prefix}deploy"}->file(@path)
            );
        }
        if (-e ( my $file = $change->revert_file )) {
            $self->_copy_if_modified(
                $file,
                $dir_for->{"${prefix}revert"}->file(@path)
            );
        }
        if (-e ( my $file = $change->verify_file )) {
            $self->_copy_if_modified(
                $file,
                $dir_for->{"${prefix}verify"}->file(@path)
            );
        }
    }

    return $self;
}

