sub execute {
    my $self = shift;
    my $plan = $self->sqitch->plan;
    my $ts_format = $self->date_format;
    my $str_format = $self->format;

    my @changes;
    my @change_ids = $self->sqitch->plan->change_ids;
    for my $change_id (@change_ids) {
        my $change = $plan->get($change_id)
            or hurl plan => __x(
                'Unknown change "{change}"',
                change => $change_id,
            );
        my $date = $change->timestamp
            or hurl plan => __x(
                'Change "{change}" has no timestamp',
                change => $change_id,
            );
        my $ts = App::Sqitch::DateTime->new(
            $date,
            $self->sqitch->sqitch->tz,
        );

        my $str = $ts_format ? $ts->as_string($ts_format) : $date;
        push @changes, {
            id       => $change_id,
            name     => $change->name,
            event    => $change->event,
            planner  => $change->planner_name,
            planner_email => $change->planner_email,
            timestamp => $str,
        };
    }

    my $formatter = App::Sqitch::ItemFormatter->new(
        format      => $str_format,
        date_format => $ts_format,
    );

    my $out = $self->sqitch->out_handle;
    my $out_fh = $self->sqitch->out_fh;

    my $last_event = '';
    my $last_planner = '';
    for my $change (@changes) {
        $change->{event} = $last_event if !$change->{event};
        $change->{planner} = $last_planner if !$change->{planner};

        $formatter->format($change);

        if ($self->keywords) {
            print $out_fh $formatter->format(
                {
                    %{ $formatter->defaults },
                    %$change,
                }
            );
        }

        $last_event = $change->{event};
        $last_planner = $change->{planner};
    }
}

