    $self->_copy( $change->revert_file, $new_change->revert_file );
    $self->_copy( $change->verify_file, $new_change->verify_file );

    # Update the plan.
    $plan->remove( $change );
    $plan->add( $new_change );
    $plan->write_to( $plan->file );

    # Update the tags.
    my $engine = $self->default_target->engine;
    my $sqitch = $self->sqitch;
    for my $tag ( $engine->tags ) {
        if ( $tag->change_id eq $change->id ) {
            $sqitch->reapply( $new_change );
        }
    }

    $self->info(__x(
        'Reworked {change}',
        change => $change->format_name_with_tags,
    ));
    return $new_change;
