                plan => $self,
                name => $name,
                dependencies => $dependencies,
                timestamp => $timestamp,
                planner_name => $planner_name,
                planner_email => $planner_email,
            );
            push @$changes => $change;
        } elsif ($line =~ /^@/) {
            # Parse the tag line.
            my ($name) = split(' ', $line, 2);
            my $tag = App::Sqitch::Plan::Tag->new(
                plan => $self,
                name => $name,
            );
            push @$tags => $tag;
        } else {
            # Skip blank lines and notes.
            next;
        }
    }

    # Return the plan data.
    return {
        changes => $changes,
        lines => $lines,
        pragmas => $pragmas,
    };
}
