  #!/usr/bin/perl

use strict;
use warnings;
use App::Sqitch::Plan::Change;
use App::Sqitch::Plan::ChangeList;
use App::Sqitch::Plan::LineList;
use App::Sqitch::X;

sub rework {
    my ( $self, %p ) = @_;

    # We need at least one name or ID.
    hurl plan => __x(
        'Cannot rework: no change or tag specified'
    ) unless $p{name} || $p{id};

    # If we have a change, get it by name.
    my $change = $self->_changes->get($p{name}) if $p{name};

    # If we don't have a change, see if it's a change ID.
    unless ($change) {
        # It's not a valid change ID.
        hurl plan => __x(
            'Cannot rework unknown change "{change}"',
            change => $p{id},
        ) if $p{id} !~ /^[0-9A-F]{40}\z/;
        $change = $self->_changes->get($p{id});
    }

    # Throw an error if the change is not in the plan.
    hurl plan => __x(
        'Cannot rework unknown change "{change}"',
        change => $p{name} || $p{id},
    ) unless $change;

    # Set the name.
    $p{name} = $change->name;

    # Check the change's dependencies.
    $self->_check_dependencies($change, 'rework');

    # Add the reworked change.
    $change = $self->_add_change(%p);

    # If there's an index, insert the new change there.
    if (defined $p{index}) {
        splice @{ $self->_changes->list }, $p{index}, 0, $change;
        $self->_changes->index_of($change) = $p{index};
    }

    # Increment the plan's position if it's not at the end.
    $self->position($self->position + 1) if $self->position < $self->count;

    return $change;
}
