sub _parse_params {
    my ( $self, $params ) = @_;
    # parse pragmas
    my @pragmas = $self->_pragmas;
    my $defaults = {};
    for my $pragma (@pragmas) {
        if ($pragma->{name} eq 'syntax-version') {
            $defaults->{syntax_version} = $pragma->{value};
        }
    }
    # add defaults
    $params->{syntax_version} ||= $defaults->{syntax_version};
    # validate params
    my @errors;
    if ($params->{limit} && ($params->{limit} <= 0)) {
        push @errors, "Limit must be a positive integer";
    }
    if ($params->{offset} && ($params->{offset} < 0)) {
        push @errors, "Offset must be a non-negative integer";
    }
    if ($params->{direction} && !($params->{direction} =~ /^(asc|desc)$/i)) {
        push @errors, "Direction must be either 'asc' or 'desc'";
    }
    if (@errors) {
        App::Sqitch::X->throw(join("\n", @errors));
    }
    # resolve change names to indices
    if (my $name = $params->{name}) {
        $params->{name_idx} = $self->_name_idx($name);
    }
    if (my $change = $params->{change}) {
        $params->{change_idx} = $self->_change_idx($change);
    }
    return $params;
